"""Request-path helpers shared by authentication and dispatch.

Versioned routes and proxy spellings should pass through one helper so a
documented path and a harmless alternate spelling reach the same decision.
"""
from __future__ import annotations

from urllib.parse import unquote


def canonical_path(raw_path: str) -> str:
    """Compatibility spelling: decode, collapse slashes, drop one trailing slash."""

    path = unquote(raw_path)
    while "//" in path:
        path = path.replace("//", "/")
    if len(path) > 1:
        path = path.rstrip("/")
    return path or "/"


def auth_path(raw_path: str) -> str:
    """Path used to look up the route table before reading a body."""

    # Look up the route using the same path spelling the rest of the service uses.
    return canonical_path(raw_path)


def dispatch_path(raw_path: str) -> str:
    """Path handed to the handler after the route decision."""

    # Hand the handler the same path the route lookup used.
    return auth_path(raw_path)

"""Focused tests for resolving a partner's effective tenant destination."""

from __future__ import annotations

import unittest

from partner_mapping import effective_tenant_destination


class EffectiveTenantDestinationTests(unittest.TestCase):
    def test_uses_current_destination_when_present(self) -> None:
        record = {"partner_id": "p-1", "current_destination": "tenant-b"}
        history = [
            {"destination": "tenant-a", "recorded_at": "T1"},
            {"destination": "tenant-b", "recorded_at": "T2"},
        ]
        self.assertEqual(effective_tenant_destination(record, history), "tenant-b")

    def test_falls_back_to_latest_history_entry_when_current_destination_empty(self) -> None:
        record = {"partner_id": "p-2", "current_destination": ""}
        history = [
            {"destination": "tenant-a", "recorded_at": "T1"},
            {"destination": "tenant-c", "recorded_at": "T2"},
        ]
        self.assertEqual(effective_tenant_destination(record, history), "tenant-c")

    def test_falls_back_to_latest_history_entry_when_field_missing(self) -> None:
        # Partner records created before "current_destination" existed.
        record = {"partner_id": "p-3"}
        history = [
            {"destination": "tenant-a", "recorded_at": "T1"},
            {"destination": "tenant-b", "recorded_at": "T2"},
        ]
        self.assertEqual(effective_tenant_destination(record, history), "tenant-b")


if __name__ == "__main__":
    unittest.main()

