        help="write the --by-team comparison table as CSV to standard output",
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_arg_parser().parse_args(argv)

    if args.file:
        path = Path(args.file)
        if not path.is_absolute():
